def _catalog():
    """service_id -> {display_name, description, urgency, max_km}; loaded once per session."""
    if 'catalog' not in _CACHE:
        rows = {}
        for r in spark.table(f'{SCHEMA}.service_catalog').collect():
            rows[r['service_id']] = {'display_name': r['display_name'], 'description': r['description'], 'urgency': r['urgency'], 'max_km': r['max_km']}
        _CACHE['catalog'] = rows
    return _CACHE['catalog']

def _synonyms():
    """(sorted phrase list, phrase_norm -> ordered service_ids); loaded once per session."""
    if 'synonyms' not in _CACHE:
        m = {}
        for r in spark.table(f'{SCHEMA}.service_synonyms').select('phrase_norm', 'service_id').collect():
            m.setdefault(r['phrase_norm'], [])
            if r['service_id'] not in m[r['phrase_norm']]:
                m[r['phrase_norm']].append(r['service_id'])
        _CACHE['synonyms'] = (sorted(m), m)
    return _CACHE['synonyms']

def _n_facilities():
    """Distinct facilities in facility_items — denominator for the 30% breadth rule."""
    if 'n_fac' not in _CACHE:
        _CACHE['n_fac'] = spark.table(f'{SCHEMA}.facility_items').select('unique_id').distinct().count()
    return _CACHE['n_fac']

def _real_specialty_labels():
    """The only allowed specialty labels: distinct camelCase codes from gold_facility_search."""
    if 'labels' not in _CACHE:
        codes = spark.table(f'{SCHEMA}.gold_facility_search').select(F.explode(F.coalesce(F.col('specialty_codes'), F.array().cast('array<string>'))).alias('c')).distinct().collect()
        _CACHE['labels'] = {r['c'] for r in codes}
    return _CACHE['labels']

def _options_for(service_ids):
    cat = _catalog()
    return [{'service_id': s, 'display_name': cat[s]['display_name'], 'description': cat[s]['description']} for s in service_ids]

def _normalize(text):
    return ' '.join(str(text).lower().split())

def _clean_list(values, lowercase=False):
    """Trim, optionally lowercase, and de-dup a list of terms; keeps camelCase labels intact."""
    if not isinstance(values, list):
        return []
    seen, out = (set(), [])
    for v in values:
        s = str(v).strip()
        if lowercase:
            s = s.lower()
        if s and s not in seen:
            seen.add(s)
            out.append(s)
    return out
CATALOG_PICK_FORMAT = 'STRUCT<answer STRUCT<service_id STRING>>'
MAPPING_FORMAT = 'STRUCT<mapping STRUCT<core_terms ARRAY<STRING>, supporting_terms ARRAY<STRING>, specialty_labels ARRAY<STRING>>>'

def _ai_query(prompt, response_format):
    """One ai_query call; returns the parsed JSON. Raises on any failure — callers must catch."""
    q = prompt.replace('\\', '\\\\').replace("'", "''")
    sql = f"SELECT ai_query('{LLM_ENDPOINT}', '{q}', responseFormat => '{response_format}', modelParameters => named_struct('temperature', 0)) AS ans"
    raw = spark.sql(sql).collect()[0][0]
    if isinstance(raw, str):
        return json.loads(raw)
    return raw.asDict() if hasattr(raw, 'asDict') else raw

def _unwrap(parsed, wrapper):
    """Some endpoints keep the wrapper field in the JSON; most return the inner fields directly."""
    if isinstance(parsed, dict) and isinstance(parsed.get(wrapper), dict):
        return parsed[wrapper]
    return parsed

def _llm_catalog_pick(norm):
    """Ask the model for exactly one catalog service_id, or NONE."""
    cat = _catalog()
    lines = '\n'.join((f"- {sid}: {info['display_name']} — {info['description']}" for sid, info in sorted(cat.items())))
    prompt = f'A user typed a healthcare service into a search box. Decide which of our checked services it refers to.\nChecked services:\n{lines}\n\nUser query: {norm}\n\nIf the query clearly refers to one of these services, answer with that service_id exactly as written. If it does not clearly match any checked service, answer NONE.\nAnswer with the service_id only.'
    parsed = _unwrap(_ai_query(prompt, CATALOG_PICK_FORMAT), 'answer')
    sid = str((parsed or {}).get('service_id') or '').strip()
    return sid or None

def _llm_generate_mapping(norm):
    """Generate core/supporting search terms + real specialty labels for a non-catalog service.
    Returns a validated mapping dict, or None if no core terms survive validation."""
    labels_sorted = sorted(_real_specialty_labels())
    prompt = f"A user typed a healthcare service need into a search box. Our facility search matches records using:\n- core_terms: short phrases that must appear in a facility's procedures/equipment/capabilities for it to be a candidate (e.g. 'hemodialysis', 'burn unit').\n- supporting_terms: adjacent capability phrases that make a candidate more credible (e.g. 'nephrology', 'skin graft').\n- specialty_labels: the facility's specialty, chosen ONLY from the allowed list below (or an empty list if none fit).\n\nUser query: {norm}\n\nAllowed specialty_labels (exact strings): {', '.join(labels_sorted)}\n\nRules: 3-5 core terms (1-3 words each, lowercase, simple spellings a facility would actually write); 2-4 supporting terms; 0-4 specialty labels from the allowed list only. If the query is not a real healthcare service or need (e.g. gibberish), return empty lists.\nReturn only the JSON."
    parsed = _unwrap(_ai_query(prompt, MAPPING_FORMAT), 'mapping')
    parsed = parsed if isinstance(parsed, dict) else {}
    core = _clean_list(parsed.get('core_terms'), lowercase=True)
    supp = _clean_list(parsed.get('supporting_terms'), lowercase=True)
    labels = _clean_list(parsed.get('specialty_labels'))
    real = _real_specialty_labels()
    dropped_labels = [t for t in labels if t not in real]
    labels = [t for t in labels if t in real]
    n_fac = _n_facilities()
    kept_core, dropped_core = ([], [])
    for t in core:
        n_match = spark.table(f'{SCHEMA}.facility_items').filter(F.col('item_class').isin('informative', 'unclear')).filter(F.col('item_key').rlike(re.escape(t))).select('unique_id').distinct().count()
        if n_match / n_fac > 0.3:
            dropped_core.append(t)
        else:
            kept_core.append(t)
    if not kept_core:
        return None
    return {'core_terms': kept_core, 'supporting_terms': supp, 'specialty_labels': labels, 'dropped_terms': dropped_core + dropped_labels}

def _ensure_generated_mappings():
    if not _table_exists('generated_mappings'):
        spark.sql(f'CREATE OR REPLACE TABLE {SCHEMA}.generated_mappings (query_norm STRING, core_terms ARRAY<STRING>, supporting_terms ARRAY<STRING>, specialty_labels ARRAY<STRING>, dropped_terms ARRAY<STRING>, created_at TIMESTAMP, times_requested INT)')

def _get_cached_mapping(norm):
    _ensure_generated_mappings()
    rows = spark.table(f'{SCHEMA}.generated_mappings').filter(F.col('query_norm') == norm).limit(1).collect()
    if not rows:
        return None
    r = rows[0]
    return {'core_terms': list(r['core_terms'] or []), 'supporting_terms': list(r['supporting_terms'] or []), 'specialty_labels': list(r['specialty_labels'] or []), 'dropped_terms': list(r['dropped_terms'] or [])}

def _save_generated_mapping(norm, mapping):
    """Insert a new generated mapping; on an existing one just bump times_requested (merge, never replace)."""
    _ensure_generated_mappings()
    new = spark.createDataFrame([(norm, mapping['core_terms'], mapping['supporting_terms'], mapping['specialty_labels'], mapping.get('dropped_terms', []), datetime.now(), 1)], 'query_norm string, core_terms array<string>, supporting_terms array<string>, specialty_labels array<string>, dropped_terms array<string>, created_at timestamp, times_requested int')
    new.createOrReplaceTempView('_gm_new')
    spark.sql(f'MERGE INTO {SCHEMA}.generated_mappings t USING _gm_new s ON t.query_norm = s.query_norm WHEN MATCHED THEN UPDATE SET t.times_requested = t.times_requested + 1 WHEN NOT MATCHED THEN INSERT *')

def _log_call(result):
    """Append every resolve_service call to query_log_service (created once, then append-only)."""
    row = spark.createDataFrame([(datetime.now(), result['input'], result['normalized'], result['status'], result['method'], result['service_id'])], 'timestamp timestamp, input string, normalized string, status string, method string, service_id string')
    if _table_exists('query_log_service'):
        row.write.mode('append').saveAsTable(f'{SCHEMA}.query_log_service')
    else:
        row.write.mode('overwrite').saveAsTable(f'{SCHEMA}.query_log_service')

def _result(text, norm):
    return {'input': str(text), 'normalized': norm, 'status': None, 'method': None, 'service_id': None, 'options': [], 'matched_phrase': None, 'mapping': None, 'confidence_cap': None, 'note': None}

def resolve_service(text, use_llm=True):
    """Resolve a typed service phrase to a checked service, a clarification request,
    an AI-generated search mapping, or none — always with the same return keys."""
    norm = _normalize(text)
    res = _result(text, norm)
    cat = _catalog()
    phrases, syn = _synonyms()
    if norm in syn:
        sids = syn[norm]
        res['matched_phrase'] = norm
        if len(sids) == 1:
            res['status'], res['method'], res['service_id'] = ('matched', 'synonym', sids[0])
            res['note'] = f"Interpreted '{text}' as {cat[sids[0]]['display_name']} (synonym match)."
        else:
            res['status'], res['method'] = ('ambiguous', 'synonym')
            res['options'] = _options_for(sids)
            names = ' or '.join((o['display_name'] for o in res['options']))
            res['note'] = f"'{text}' could mean {names} — please pick one."
        _log_call(res)
        return res
    close = difflib.get_close_matches(norm, phrases, n=3, cutoff=0.85)
    if close:
        sids = []
        for p in close:
            for s in syn[p]:
                if s not in sids:
                    sids.append(s)
        res['matched_phrase'] = close[0]
        if len(sids) == 1:
            res['status'], res['method'], res['service_id'] = ('matched', 'fuzzy_synonym', sids[0])
            res['note'] = f"Interpreted '{text}' as {cat[sids[0]]['display_name']} (close to '{close[0]}')."
        else:
            res['status'], res['method'] = ('ambiguous', 'fuzzy_synonym')
            res['options'] = _options_for(sids)
            names = ' or '.join((o['display_name'] for o in res['options']))
            res['note'] = f"'{text}' could mean {names} — please pick one."
        _log_call(res)
        return res
    llm_failed = False
    if use_llm:
        try:
            picked = _llm_catalog_pick(norm)
            if picked in cat:
                res['status'], res['method'], res['service_id'] = ('matched', 'llm_catalog_pick', picked)
                res['note'] = f"Interpreted '{text}' as {cat[picked]['display_name']} (AI catalog pick)."
                _log_call(res)
                return res
        except Exception as e:
            llm_failed = True
            print(f'LLM catalog pick failed for {norm!r}: {e}')
    if use_llm and (not llm_failed):
        try:
            cached = _get_cached_mapping(norm)
            if cached is not None:
                res['status'], res['method'] = ('generated', 'llm_generated')
                res['mapping'] = cached
                res['confidence_cap'] = 'moderate'
                res['note'] = f"No checked service matched; reusing a previously generated search for '{text}'."
                _save_generated_mapping(norm, cached)
                _log_call(res)
                return res
            generated = _llm_generate_mapping(norm)
            if generated is not None:
                res['status'], res['method'] = ('generated', 'llm_generated')
                res['mapping'] = generated
                res['confidence_cap'] = 'moderate'
                _save_generated_mapping(norm, generated)
                res['note'] = f"No checked service matched; generated a search for '{text}' (moderate confidence)."
                _log_call(res)
                return res
        except Exception as e:
            llm_failed = True
            print(f'LLM mapping generation failed for {norm!r}: {e}')
    res['status'] = 'none'
    if use_llm and llm_failed:
        res['note'] = f"Could not resolve '{text}'; the AI fallback was unavailable."
    else:
        res['note'] = f"Could not resolve '{text}' to any checked service or search."
    _log_call(res)
    return res

# ===== Step 1 — resolve_location =====
INDIA_LAT = (6.0, 37.6)
INDIA_LON = (68.0, 97.5)
PIN_RE = re.compile('(?<!\\d)[1-8]\\d{5}(?!\\d)')
COORD_RE = re.compile('^\\(?\\s*(-?\\d{1,2}(?:\\.\\d+)?)\\s*[,\\s]\\s*(-?\\d{1,3}(?:\\.\\d+)?)\\s*\\)?$')
DISTRICT_SUFFIX = {'urban', 'rural', 'city', 'district', 'dist', 'dt'}
LOC_FUZZY_CUTOFF = 0.81
LOCATION_ALIASES = {'bangalore': 'bengaluru urban', 'bengaluru': 'bengaluru urban', 'blr': 'bengaluru urban', 'bengalooru': 'bengaluru urban', 'bombay': 'mumbai', 'madras': 'chennai', 'calcutta': 'kolkata', 'gurgaon': 'gurugram', 'poona': 'pune', 'baroda': 'vadodara', 'trivandrum': 'thiruvananthapuram', 'cochin': 'ernakulam', 'kochi': 'ernakulam', 'calicut': 'kozhikode', 'vizag': 'visakhapatanam', 'visakhapatnam': 'visakhapatanam', 'vishakhapatnam': 'visakhapatanam', 'benares': 'varanasi', 'banaras': 'varanasi', 'kashi': 'varanasi', 'allahabad': 'prayagraj', 'pondicherry': 'puducherry', 'pondy': 'puducherry', 'mysore': 'mysuru', 'mangalore': 'dakshina kannada', 'mangaluru': 'dakshina kannada', 'belgaum': 'belagavi', 'gulbarga': 'kalaburagi', 'shimoga': 'shivamogga', 'tumkur': 'tumakuru', 'bellary': 'ballari', 'trichy': 'tiruchirappalli', 'faizabad': 'ayodhya', 'noida': 'gautam buddha nagar', 'greater noida': 'gautam buddha nagar', 'navi mumbai': 'thane', 'secunderabad': 'hyderabad', 'hubli': 'dharwad', 'hubballi': 'dharwad', 'vijayawada': 'krishna', 'orissa': 'odisha', 'uttaranchal': 'uttarakhand'}
STATE_ABBREVIATIONS = {'up': 'Uttar Pradesh', 'mp': 'Madhya Pradesh', 'tn': 'Tamil Nadu', 'wb': 'West Bengal', 'ap': 'Andhra Pradesh', 'hp': 'Himachal Pradesh', 'jk': 'Jammu and Kashmir', 'j and k': 'Jammu and Kashmir', 'mh': 'Maharashtra', 'ka': 'Karnataka', 'kl': 'Kerala', 'gj': 'Gujarat', 'rj': 'Rajasthan', 'pb': 'Punjab', 'hr': 'Haryana', 'br': 'Bihar', 'od': 'Odisha', 'ts': 'Telangana', 'tg': 'Telangana', 'uk': 'Uttarakhand', 'cg': 'Chhattisgarh', 'jh': 'Jharkhand', 'ga': 'Goa', 'dl': 'Delhi', 'nct': 'Delhi'}
_SIZE_RANK = {'state': 0, 'district': 1, 'city': 2, 'village': 3}

def _lnorm(s):
    s = str(s or '').lower().replace('&', ' and ')
    s = re.sub('[^a-z0-9,\\s.-]', ' ', s)
    return re.sub('\\s+', ' ', s).strip(' .,-')

def _dkey(name):
    """District key without Urban/Rural/City/District words: 'bengaluru urban' -> 'bengaluru'."""
    words = [w for w in _lnorm(name).split() if w not in DISTRICT_SUFFIX]
    return ' '.join(words) or _lnorm(name)

def _geo():
    """Load 03_geo's gazetteer once: districts, towns, PIN centres, states."""
    if 'geo' not in _CACHE:
        gl = spark.table(f'{SCHEMA}.geo_lookup').where("type IN ('district', 'town') AND lat IS NOT NULL").select('place', 'type', 'lat', 'lon', 'district', 'state', 'n_pins').toPandas()
        pc = spark.table(f'{SCHEMA}.pin_centers').where('lat IS NOT NULL').select('pincode', 'lat', 'lon', 'district', 'state').toPandas()
        d = gl[gl['type'] == 'district'].copy()
        d['key'] = d['place'].map(_dkey)
        pcd = pc.merge(d[['district', 'state', 'lat', 'lon']].rename(columns={'lat': 'dlat', 'lon': 'dlon'}), on=['district', 'state'])
        pcd['km'] = _hav_np_rows(pcd['lat'], pcd['lon'], pcd['dlat'], pcd['dlon'])
        rad = pcd.groupby(['district', 'state'])['km'].median().clip(3, 25)
        d = d.join(rad.rename('radius_km'), on=['district', 'state'])
        d['radius_km'] = d['radius_km'].fillna(15.0)
        t = gl[gl['type'] == 'town'].copy()
        states = sorted(d['state'].dropna().unique())
        _CACHE['geo'] = {'districts': d, 'towns': t, 'pins': pc.set_index('pincode'), 'states': states, 'state_by_name': {**{_lnorm(s): s for s in states}, **STATE_ABBREVIATIONS}, 'district_keys': sorted(d['key'].unique()), 'town_names': sorted(t['place'].unique())}
    return _CACHE['geo']

def _hav_np_rows(la1, lo1, la2, lo2):
    la1, lo1, la2, lo2 = (np.radians(np.asarray(x, dtype=float)) for x in (la1, lo1, la2, lo2))
    h = np.sin((la2 - la1) / 2) ** 2 + np.cos(la1) * np.cos(la2) * np.sin((lo2 - lo1) / 2) ** 2
    return 2 * 6371.0088 * np.arcsin(np.sqrt(h))

def _loc_result(text):
    return {'input': str(text if text is not None else ''), 'status': 'none', 'method': None, 'lat': None, 'lon': None, 'radius_km': None, 'label': None, 'district': None, 'state': None, 'options': [], 'note': None}

def _nice(x):
    """Title-case lowercase names; leave 'PIN 560001' / '12.97, 77.59' / 'Bengaluru Urban' as they are."""
    x = str(x)
    return _title(x) if x == x.lower() and (not x[:1].isdigit()) else x

def _resolved(res, method, lat, lon, radius_km, place, district, state, note):
    district = _nice(district) if district else None
    label = ', '.join((x for x in [_nice(place) if place and _lnorm(place) != _lnorm(district) else None, (district if district.lower().endswith('district') else f'{district} district') if district else None, state] if x))
    note = note.replace('{label}', label).replace('{r:.0f}', f'{float(radius_km):.0f}')
    res.update({'status': 'resolved', 'method': method, 'lat': float(lat), 'lon': float(lon), 'radius_km': float(radius_km), 'label': label, 'district': district, 'state': state, 'note': note})
    return res

def _option(name, kind, district, state):
    name, district = (_nice(name), _nice(district) if district else None)
    query = f'{state}' if kind == 'state' else f'{name}, {state}' if kind == 'district' else f'{name}, {district}, {state}'
    shown = name if kind == 'state' else f'{name} ({kind}), {state}' if kind == 'district' else f'{name}, {district}, {state}'
    return {'name': name, 'district': district, 'state': state, 'type': kind, 'query': query, 'display': shown}

def _ambiguous(res, method, options, note):
    res.update({'status': 'ambiguous', 'method': method, 'options': options, 'note': note})
    return res

def _split_suffix(s, g):
    """'aurangabad, maharashtra' -> ('aurangabad', None, 'Maharashtra');
    'manchar, pune, maharashtra' -> ('manchar', 'pune', 'Maharashtra')."""
    parts = [p.strip() for p in s.split(',') if p.strip() and p.strip() != 'india']
    state = district = None
    if len(parts) >= 2 and parts[-1] in g['state_by_name']:
        state = g['state_by_name'][parts[-1]]
        parts = parts[:-1]
    if len(parts) >= 2:
        dk = _dkey(parts[-1])
        dd = g['districts']
        hit = dd[(dd['key'] == dk) & (dd['state'] == state if state else True)]
        if len(hit):
            district = hit.iloc[0]['place']
            parts = parts[:-1]
    return (', '.join(parts) if parts else district or '', district, state)

def _match_district(q, g, state=None):
    d = g['districts']
    hit = d[d['key'] == _dkey(q)]
    if state:
        hit = hit[hit['state'] == state]
    return hit.sort_values('n_pins', ascending=False)

def _district_point(row, g):
    """Centre a district input on its same-named town when there is one ('Pune' → Pune city), else the
    district centre."""
    t = g['towns']
    key = _dkey(row['place'])
    same = t[(t['district'] == row['district']) & (t['state'] == row['state']) & t['place'].isin({row['place'], key, key + ' city'})]
    if len(same):
        same = same.assign(_exact=(same['place'] != key + ' city').astype(int), _km=_hav_np_rows(same['lat'], same['lon'], row['lat'], row['lon']))
        same = same[same['_km'] <= 25]
        if len(same):
            s = same.sort_values(['_exact', 'n_pins'], ascending=False).iloc[0]
            return (s['lat'], s['lon'], 5.0, 'district_town')
    return (row['lat'], row['lon'], row['radius_km'], 'district')

def _fuzzy_options(q, g, state=None):
    cands = []
    for s in difflib.get_close_matches(q, list(g['state_by_name']), n=3, cutoff=LOC_FUZZY_CUTOFF):
        if len(s) > 3:
            cands.append((0, -difflib.SequenceMatcher(None, q, s).ratio(), _option(g['state_by_name'][s], 'state', None, g['state_by_name'][s])))
    d = g['districts'] if not state else g['districts'][g['districts']['state'] == state]
    for k in difflib.get_close_matches(q, sorted(d['key'].unique()), n=5, cutoff=LOC_FUZZY_CUTOFF):
        for r in d[d['key'] == k].itertuples():
            cands.append((1, -difflib.SequenceMatcher(None, q, k).ratio(), _option(r.place, 'district', r.district, r.state)))
    t = g['towns'] if not state else g['towns'][g['towns']['state'] == state]
    names = g['town_names'] if not state else sorted(t['place'].unique())
    for n in difflib.get_close_matches(q, names, n=5, cutoff=LOC_FUZZY_CUTOFF):
        for r in t[t['place'] == n].sort_values('n_pins', ascending=False).head(2).itertuples():
            kind = 'city' if r.n_pins >= 3 else 'village'
            cands.append((_SIZE_RANK[kind], -difflib.SequenceMatcher(None, q, n).ratio(), _option(r.place, kind, r.district, r.state)))
    seen, out = (set(), [])
    for _, _, o in sorted(cands, key=lambda x: (x[0], x[1])):
        if o['query'] not in seen:
            seen.add(o['query'])
            out.append(o)
    return out[:3]

def resolve_location(text):
    """STEP 1 — free-text location -> resolved point + honest radius, or a clarification request."""
    g = _geo()
    res = _loc_result(text)
    s = _lnorm(text)
    if not s:
        res['note'] = 'Please enter a place, a PIN, or coordinates.'
        return res
    m = COORD_RE.match(s.replace(' ,', ','))
    if m:
        lat, lon = (float(m.group(1)), float(m.group(2)))
        if INDIA_LAT[0] <= lat <= INDIA_LAT[1] and INDIA_LON[0] <= lon <= INDIA_LON[1]:
            pins = g['pins']
            j = int(np.argmin(_hav_np_rows(lat, lon, pins['lat'].to_numpy(), pins['lon'].to_numpy())))
            near = pins.iloc[j]
            return _resolved(res, 'coordinates', lat, lon, 0.0, f'{lat:.4f}, {lon:.4f}', near['district'], near['state'], 'Using the coordinates you provided (near {label}).')
        res['note'] = f"'{text}' does not look like a location in India."
        return res
    pm = PIN_RE.search(s)
    if pm:
        pin = pm.group(0)
        if pin in g['pins'].index:
            p = g['pins'].loc[pin]
            return _resolved(res, 'pin', p['lat'], p['lon'], 5.0, f'PIN {pin}', p['district'], p['state'], 'Centered on PIN ' + pin + " ({label}); distances measured from the PIN's post offices, ±{r:.0f} km.")
        if s == pin:
            res['note'] = f'PIN {pin} is not in the India Post directory.'
            return res
    q, in_district, in_state = _split_suffix(s, g)
    q = re.sub('\\b(district|dist|city|town|village)\\b', ' ', q).strip() or q
    q = re.sub('\\s+', ' ', q)
    alias = LOCATION_ALIASES.get(q)
    q2 = alias or q
    if q2 in g['state_by_name'] and (not in_district):
        st = g['state_by_name'][q2]
        d = g['districts'][g['districts']['state'] == st].sort_values('n_pins', ascending=False)
        if len(d) == 1:
            r = d.iloc[0]
            lat, lon, rad, how = _district_point(r, g)
            return _resolved(res, how, lat, lon, rad, r['district'], r['district'], st, 'Centered on {label}, ±{r:.0f} km.')
        return _ambiguous(res, 'state', [_option(r.place, 'district', r.district, st) for r in d.itertuples()], f'{st} is a state — which district?')
    hit = _match_district(q2, g, in_state)
    if len(hit):
        if hit['state'].nunique() > 1:
            return _ambiguous(res, 'district', [_option(r.place, 'district', r.district, r.state) for r in hit.itertuples()], f"{_title(q2)} is a district in more than one state ({', '.join(sorted(hit['state'].unique()))}) — which one?")
        r = hit.iloc[0]
        lat, lon, rad, how = _district_point(r, g)
        typed = str(text).replace('{', '(').replace('}', ')')
        note = 'Centered on {label}' + (f" (you typed '{typed}')" if alias else '') + ', ±{r:.0f} km.'
        return _resolved(res, how, lat, lon, rad, r['district'], r['district'], r['state'], note)
    t = g['towns']
    th = t[t['place'] == q2]
    if in_state:
        th = th[th['state'] == in_state]
    if in_district:
        th = th[th['district'].str.lower() == in_district]
    if len(th):
        th = th.sort_values('n_pins', ascending=False)
        top = th.iloc[0]
        close_d = [] if in_state or in_district else difflib.get_close_matches(q2, g['district_keys'], n=2, cutoff=0.85)
        if top['n_pins'] <= 1 and close_d:
            opts = [_option(r.place, 'district', r.district, r.state) for k in close_d for r in g['districts'][g['districts']['key'] == k].itertuples()][:2]
            opts.append(_option(top['place'], 'village', top['district'], top['state']))
            return _ambiguous(res, 'town_or_district', opts, f"Did you mean {opts[0]['display']}, or the village {_nice(top['place'])} in {top['state']}?")
        if len(th) == 1 or top['n_pins'] > th.iloc[1]['n_pins']:
            rad = 3.0 if top['n_pins'] <= 2 else 6.0
            return _resolved(res, 'town', top['lat'], top['lon'], rad, top['place'], top['district'], top['state'], 'Centered on {label}, ±{r:.0f} km.')
        opts = [_option(r.place, 'city' if r.n_pins >= 3 else 'village', r.district, r.state) for r in th.head(3).itertuples()]
        return _ambiguous(res, 'town', opts, f'There are several places called {_title(q2)} — which one?')
    opts = _fuzzy_options(q2, g, in_state)
    if opts:
        return _ambiguous(res, 'fuzzy', opts, f"Couldn't find '{text}' exactly — did you mean one of these?")
    res['note'] = "We couldn't find that place. Add the district/state or use a PIN code."
    return res

# ===== Step 2 — get_candidates =====
TIER_BASE = {'strong': 0.7, 'moderate': 0.45, 'weak': 0.15}

def _dist_col(lat, lon):
    """Spark column: haversine km from the user point to final_lat/final_lon."""
    la, lo = (math.radians(lat), math.radians(lon))
    fla, flo = (F.radians(F.col('final_lat')), F.radians(F.col('final_lon')))
    return F.lit(6371.0) * 2.0 * F.asin(F.sqrt(F.pow(F.sin((fla - F.lit(la)) / F.lit(2.0)), 2) + F.lit(math.cos(la)) * F.cos(fla) * F.pow(F.sin((flo - F.lit(lo)) / F.lit(2.0)), 2)))

def _base_facilities():
    """One row per facility from the government-verified Gold table (09b), in the column names the rest
    of the engine uses. Coordinates, confidence and notes are the cleaned + verified ones (location vote,
    government directory); possible_merged_record comes from facilities_silver."""
    conf_to_tier = F.when(F.col('location_confidence') == 'high', 'low').when(F.col('location_confidence') == 'medium', 'medium').otherwise('high')
    gold = spark.table(FACILITY_TABLE).select('unique_id', 'name', 'facility_type', 'number_doctors', 'capacity_beds', 'phone', 'phone_numbers', 'website', 'specialty_codes', F.col('latitude').alias('final_lat'), F.col('longitude').alias('final_lon'), 'location_error_km', conf_to_tier.alias('uncertainty_tier'), F.col('location_note').alias('location_evidence'), 'location_warnings', 'location_source')
    merged = spark.table(f'{SCHEMA}.facilities_silver').select('unique_id', F.coalesce(F.col('possible_merged_record'), F.lit(False)).alias('possible_merged_record'))
    return gold.join(merged, 'unique_id', 'left').fillna({'possible_merged_record': False})
_CAND_COLS = ['unique_id', 'name', 'facility_type', 'number_doctors', 'capacity_beds', 'phone', 'phone_numbers', 'website', 'specialty_codes', 'final_lat', 'final_lon', 'location_error_km', 'uncertainty_tier', 'location_evidence', 'location_warnings', 'possible_merged_record', 'service_id', 'evidence_tier', 'evidence_score', 'evidence_snippets', 'evidence_text', 'boilerplate', 'contradiction', 'distance_km']

def _matched_candidates(service_id, location):
    """Evidence rows for a checked service (strong/moderate/weak), joined to located facilities."""
    d = _dist_col(location['lat'], location['lon'])
    df = spark.table(f'{SCHEMA}.facility_service_evidence').filter(F.col('service_id') == service_id).filter(F.col('evidence_tier').isin('strong', 'moderate', 'weak')).select('unique_id', 'service_id', 'evidence_tier', 'evidence_score', 'evidence_snippets', 'evidence_text', 'boilerplate', 'contradiction').join(_base_facilities(), 'unique_id', 'inner').filter(F.col('final_lat').isNotNull()).withColumn('distance_km', d)
    return df.toPandas()[_CAND_COLS]

def _gen_evidence_text(first_items, specialty_support, tier):
    parts = [f"{_title(f)} lists '{str(it)}'" for f, it in first_items]
    txt = ''
    if parts:
        txt = '; '.join(parts) + '.'
    if specialty_support:
        txt += ' A listed specialty matches this need.'
    if tier == 'weak':
        txt += ' Specialty or related terms only.'
    return txt if txt else 'Matched on related text.'

def _generated_candidates(mapping, location, radius_km):
    """Generated services: restrict facilities to the radius first, then match the mapping's core
    and supporting terms against facility_items (informative/unclear) with notebook-04 tier logic,
    capped at 'moderate'. radius_km=None means no distance cap (used for the honest no_results text)."""
    d = _dist_col(location['lat'], location['lon'])
    fac = _base_facilities().filter(F.col('final_lat').isNotNull()).withColumn('distance_km', d)
    if radius_km is not None:
        fac = fac.filter(F.col('distance_km') <= F.lit(float(radius_km)))
    core_terms = list(mapping.get('core_terms') or [])
    supp_terms = list(mapping.get('supporting_terms') or [])
    labels = list(mapping.get('specialty_labels') or [])
    items = spark.table(f'{SCHEMA}.facility_items').filter(F.col('item_class').isin('informative', 'unclear')).join(fac.select('unique_id'), 'unique_id', 'inner')
    if core_terms:
        core_re = '|'.join((re.escape(t) for t in core_terms))
        items = items.withColumn('core_hit', F.col('item_key').rlike(core_re))
    else:
        items = items.withColumn('core_hit', F.lit(False))
    if supp_terms:
        supp_re = '|'.join((re.escape(t) for t in supp_terms))
        items = items.withColumn('supp_hit', F.col('item_key').rlike(supp_re))
    else:
        items = items.withColumn('supp_hit', F.lit(False))
    items = items.filter(F.col('core_hit') | F.col('supp_hit'))
    per = items.groupBy('unique_id').agg(F.collect_set(F.when(F.col('core_hit'), F.col('field'))).alias('core_fields'), F.collect_set(F.when(F.col('supp_hit'), F.col('field'))).alias('supporting_fields'), F.slice(F.collect_list(F.struct(F.col('field').alias('field'), F.col('item').alias('item'))), 1, 3).alias('first_items'))
    if labels:
        spec_col = F.size(F.array_intersect(F.coalesce(F.col('specialty_codes'), F.array().cast('array<string>')), F.array(*[F.lit(x) for x in labels]))) > 0
    else:
        spec_col = F.lit(False)
    boiler = spark.table(f'{SCHEMA}.service_fields_parsed').select('unique_id', F.col('possible_boilerplate').alias('boilerplate_flag'))
    ev = fac.join(per, 'unique_id', 'left').join(boiler, 'unique_id', 'left').withColumn('specialty_support', spec_col).filter((F.size(F.coalesce(F.col('core_fields'), F.array())) > 0) | (F.size(F.coalesce(F.col('supporting_fields'), F.array())) > 0) | F.col('specialty_support'))
    pdf = ev.toPandas()
    rows = []
    for _, r in pdf.iterrows():
        core_fields = sorted(set(_arr(r['core_fields'])))
        supp_fields = sorted(set(_arr(r['supporting_fields'])))
        spec = bool(r['specialty_support'])
        tier = 'moderate' if core_fields else 'weak'
        first_items = [(x['field'], x['item']) for x in _arr(r['first_items'])]
        rows.append({'unique_id': r['unique_id'], 'name': r['name'], 'facility_type': r['facility_type'], 'number_doctors': r['number_doctors'], 'capacity_beds': r['capacity_beds'], 'phone': r['phone'], 'phone_numbers': r['phone_numbers'], 'website': r['website'], 'specialty_codes': r['specialty_codes'], 'final_lat': r['final_lat'], 'final_lon': r['final_lon'], 'location_error_km': r['location_error_km'], 'uncertainty_tier': r['uncertainty_tier'], 'location_evidence': r['location_evidence'], 'location_warnings': r['location_warnings'], 'possible_merged_record': r['possible_merged_record'], 'service_id': None, 'evidence_tier': tier, 'evidence_score': float(min(1.0, 0.4 * len(core_fields) + 0.2 * len(supp_fields) + (0.4 if spec else 0.0))), 'evidence_snippets': [f"{f}: '{it}'" for f, it in first_items], 'evidence_text': _gen_evidence_text(first_items, spec, tier), 'boilerplate': bool(r['boilerplate_flag']) if not pd.isna(r['boilerplate_flag']) else False, 'contradiction': False, 'distance_km': float(r['distance_km'])})
    return pd.DataFrame(rows, columns=_CAND_COLS) if rows else pd.DataFrame(columns=_CAND_COLS)

def _widen(cand, base_max):
    """STEP 2 widening: 1.5x max_km, then 3x, then also weak evidence — until 3 options are found
    or all steps are used. Returns (kept_df, radius_km, notes, widened_weak)."""
    tiers_core = ['strong', 'moderate']
    base = cand[cand['evidence_tier'].isin(tiers_core) & (cand['distance_km'] <= base_max)]
    if len(base) >= 3:
        return (base, float(base_max), [], False)
    notes = [f'No strong or moderate evidence within {base_max:.0f} km.']
    steps = [(1.5, tiers_core, 'Widened the search to {r:.0f} km'), (3.0, tiers_core, 'Widened the search to {r:.0f} km'), (3.0, tiers_core + ['weak'], 'Also included weaker evidence (specialty or related terms only)')]
    radius, best, best_weak = (float(base_max), base, False)
    for mult, tiers, tpl in steps:
        radius = float(base_max) * mult
        sub = cand[cand['evidence_tier'].isin(tiers) & (cand['distance_km'] <= radius)]
        action = tpl.format(r=radius)
        if len(sub) >= 3:
            notes.append(action + '.')
            return (sub, radius, notes, 'weak' in tiers)
        notes.append(f'Still fewer than 3 options within {radius:.0f} km.')
        if len(sub) > len(best):
            best, best_weak = (sub, 'weak' in tiers)
    return (best, radius, notes, best_weak)

def _nearest_evidence(cand, kind, mapping, location):
    """Nearest strong/moderate/weak evidence overall — for the honest no_results message."""
    tiers = ['strong', 'moderate', 'weak']
    wide = cand[cand['evidence_tier'].isin(tiers)] if len(cand) else cand
    if kind == 'generated' and len(wide) == 0:
        wide = _generated_candidates(mapping, location, radius_km=None)
        if len(wide):
            wide = wide[wide['evidence_tier'].isin(tiers)]
    if len(wide) == 0:
        return None
    i = wide['distance_km'].idxmin()
    r = wide.loc[i]
    return {'unique_id': r['unique_id'], 'name': r['name'], 'distance_km': round(float(r['distance_km']), 1), 'evidence_tier': r['evidence_tier']}

def get_candidates(service_resolution, location):
    """STEP 2 — candidates + widening + honest nearest-evidence. Returns a dict."""
    cat = _catalog()
    if service_resolution['status'] == 'matched':
        service_id = service_resolution['service_id']
        base_max = int(cat[service_id]['max_km'])
        cand = _matched_candidates(service_id, location)
        kind = 'matched'
    elif service_resolution['status'] == 'generated':
        base_max = 150
        cand = _generated_candidates(service_resolution['mapping'], location, radius_km=base_max)
        kind = 'generated'
    else:
        raise ValueError('get_candidates needs a matched or generated service resolution')
    kept, radius, notes, weak_used = _widen(cand, base_max)
    return {'candidates': kept, 'service_kind': kind, 'base_max_km': float(base_max), 'search_radius_km': radius, 'search_notes': notes, 'widened_weak': weak_used, 'nearest_evidence': None if len(kept) > 0 else _nearest_evidence(cand, kind, service_resolution.get('mapping'), location)}

# ===== Step 3 — score_candidates =====
DECAY_KM = {'emergency': 30.0, 'recurring': 80.0, 'planned': 200.0}
WEIGHTS = {'emergency': {'evidence': 0.35, 'access': 0.4, 'readiness': 0.15, 'trust': 0.1}, 'recurring': {'evidence': 0.4, 'access': 0.3, 'readiness': 0.15, 'trust': 0.15}, 'planned': {'evidence': 0.5, 'access': 0.15, 'readiness': 0.2, 'trust': 0.15}}
LOG50 = math.log1p(50)

def urgency_for(service_resolution):
    """Urgency from service_catalog; generated services use 'planned'."""
    if service_resolution['status'] == 'matched':
        return _catalog()[service_resolution['service_id']]['urgency']
    return 'planned'

def _has_phone(row):
    p = row.get('phone')
    if isinstance(p, str) and p.strip():
        return True
    v = row.get('phone_numbers')
    return v is not None and len(_arr(v)) > 0

def score_candidates(cand, urgency):
    df = cand.copy()
    decay = DECAY_KM[urgency]
    df['evidence_component'] = df['evidence_tier'].map(TIER_BASE).astype(float) + 0.3 * df['evidence_score'].fillna(0.0).astype(float)
    err = df['location_error_km'].fillna(0.0).astype(float)
    df['access_component'] = np.exp(-(df['distance_km'].astype(float) + err) / decay)
    ft = df['facility_type'].str.lower().map({'hospital': 1.0, 'clinic': 0.5}).fillna(0.3)
    docs = np.where(df['number_doctors'].isna(), 0.3, np.minimum(np.log1p(df['number_doctors'].fillna(0.0)) / LOG50, 1.0))
    cap = np.where(df['capacity_beds'].isna(), 0.3, np.minimum(np.log1p(df['capacity_beds'].fillna(0.0)) / LOG50, 1.0))
    df['readiness_component'] = (ft.astype(float) + docs + cap) / 3.0
    has_phone = df.apply(_has_phone, axis=1)
    web = df['website'].fillna('').astype(str).str.strip().ne('')
    no_merge = ~df['possible_merged_record'].fillna(False).astype(bool)
    ut = df['uncertainty_tier'].str.lower().map({'low': 1.0, 'medium': 0.6, 'high': 0.2}).fillna(0.6)
    df['trust_component'] = (has_phone.astype(float) + web.astype(float) + no_merge.astype(float) + ut.astype(float)) / 4.0
    w = WEIGHTS[urgency]
    df['final_score'] = w['evidence'] * df['evidence_component'] + w['access'] * df['access_component'] + w['readiness'] * df['readiness_component'] + w['trust'] * df['trust_component']
    return df

# ===== Steps 4+5 — pick_top3 and explanations =====
COMPONENT_PHRASES = {'evidence': 'its service evidence', 'access': 'being close to you', 'readiness': 'its readiness (staff and capacity)', 'trust': 'verifiable contact and location details'}

def pick_top3(scored):
    """Returns a list of {'role', 'row'} picks, at most 3, with the STEP 4 roles.
    Slot 1 Best overall; slot 2 Closest credible option (nearest unused strong/moderate);
    slot 3 next-highest final_score, unless the Strongest-evidence role adds a facility
    within 1.5x the Best-overall pick's distance. Never fills a slot with a facility more
    than 3x farther than an unused strong or moderate candidate (so a far pick can never
    displace a near credible option). Facilities flagged possible_merged_record are a last
    resort: named roles and the fill come from clean records whenever any exist, and
    flagged records are only used to reach 3 options (always shown with a warning)."""
    if len(scored) == 0:
        return []
    tier_rank = {'strong': 0, 'moderate': 1, 'weak': 2}
    df = scored.assign(_score_r=scored['final_score'].astype(float).round(2), _tier_r=scored['evidence_tier'].map(tier_rank).fillna(3), _uid=scored['unique_id'].astype(str)).sort_values(['_score_r', '_tier_r', 'distance_km', '_uid'], ascending=[False, True, True, True]).drop(columns=['_score_r', '_tier_r', '_uid']).reset_index(drop=True)
    flagged = df['possible_merged_record'].fillna(False).astype(bool)
    clean = df[~flagged]
    pool = clean if len(clean) > 0 else df
    picks, used = ([], set())

    def too_far(row):
        """Would this pick be more than 3x farther than an unused strong/moderate candidate?
        (Flagged records count as candidates: strong evidence at 3 km still blocks a pick
        at 95 km, even while the flagged record itself is held back.)"""
        cred = df[~df['unique_id'].isin(used | {row['unique_id']})]
        cred = cred[cred['evidence_tier'].isin(['strong', 'moderate'])]
        if len(cred) == 0:
            return False
        return float(row['distance_km']) > 3.0 * float(cred['distance_km'].min())

    def take(row, role):
        uid = row['unique_id']
        if uid in used or too_far(row):
            return
        used.add(uid)
        picks.append({'role': role, 'row': row})

    def first_ok(frame):
        for _, r in frame.iterrows():
            if not too_far(r):
                return r
        return None
    best = first_ok(pool)
    if best is None:
        best = first_ok(df)
        if best is None:
            best = df.iloc[0]
        used.add(best['unique_id'])
        picks.append({'role': 'Best overall', 'row': best})
    else:
        take(best, 'Best overall')
    best_d = float(picks[0]['row']['distance_km'])
    cred = pool[~pool['unique_id'].isin(used) & pool['evidence_tier'].isin(['strong', 'moderate'])]
    if len(cred):
        take(cred.sort_values('distance_km').iloc[0], 'Closest credible option')
    if len(picks) < 3:
        rest = pool[~pool['unique_id'].isin(used)]
        if len(rest):
            ev = rest.sort_values('evidence_component', ascending=False).iloc[0]
            if float(ev['distance_km']) <= 1.5 * best_d:
                take(ev, 'Strongest evidence')
    for _, row in pool.iterrows():
        if len(picks) >= 3:
            break
        take(row, 'Next best option')
    if len(picks) < 3:
        for _, row in df.iterrows():
            if len(picks) >= 3:
                break
            take(row, 'Next best option')
    return picks

def explain_result(pick, service_resolution, weights):
    """STEP 5 — the fixed explanation template for one result."""
    r, role = (pick['row'], pick['role'])
    warnings = list(_arr(r.get('location_warnings')))
    if bool(r.get('boilerplate')):
        warnings.append('Some listed services may be boilerplate text repeated across many facilities.')
    if r['evidence_tier'] == 'weak':
        warnings.append('Matched on specialty or related terms only — not a direct mention of the service.')
    if service_resolution['status'] == 'generated':
        warnings.append(f"Best-effort search using AI-generated terms for '{service_resolution['input']}' — not a checked service.")
    if bool(r.get('contradiction')):
        warnings.append('Some fields hint this service may NOT be offered here — call before travelling.')
    if bool(r.get('possible_merged_record')):
        warnings.append('This record may merge two facilities; details may be unreliable.')
    contribs = {k: weights[k] * float(r[f'{k}_component']) for k in COMPONENT_PHRASES}
    top2 = sorted(contribs, key=contribs.get, reverse=True)[:2]
    why_ranked = f'Chosen mainly for {COMPONENT_PHRASES[top2[0]]} and {COMPONENT_PHRASES[top2[1]]}.'
    phone = r.get('phone')
    if not (isinstance(phone, str) and phone.strip()):
        nums = _arr(r.get('phone_numbers'))
        phone = str(nums[0]) if nums else ''
    contact = f'Phone: {phone}. ' if phone else 'No phone number on record. '
    contact += 'Call ahead to confirm the service is available today.'
    err = r.get('location_error_km')
    err_txt = '' if pd.isna(err) else f' ±{float(err):.0f} km'
    return {'unique_id': r['unique_id'], 'name': r['name'], 'role': role, 'distance_km': round(float(r['distance_km']), 1), 'final_score': round(float(r['final_score']), 2), 'evidence_tier': r['evidence_tier'], 'lat': float(r['final_lat']), 'lon': float(r['final_lon']), 'phone': phone, 'website': r.get('website') or None, 'possible_merged_record': bool(r.get('possible_merged_record')), 'components': {k: round(float(r[f'{k}_component']), 2) for k in COMPONENT_PHRASES}, 'headline': f"{r['name']} — {float(r['distance_km']):.0f} km{err_txt} — {role}", 'why_service': f"{r['evidence_text']} (evidence tier: {r['evidence_tier']})", 'why_location': r.get('location_evidence'), 'why_ranked': why_ranked, 'contact': contact, 'warnings': warnings, 'caveat': 'All service information is self-reported by the facility.'}

def how_we_decided(service_resolution, location, urgency, search_notes, final_radius_km):
    """The whole-query explanation: how the service and location were interpreted, the weights
    used and why (urgency), and any widening."""
    svc = service_resolution['note']
    if service_resolution['status'] == 'generated':
        m = service_resolution.get('mapping') or {}
        svc = f"{svc} Search terms used: core {', '.join(m.get('core_terms') or []) or '—'}; supporting {', '.join(m.get('supporting_terms') or []) or '—'}; specialty labels {', '.join(m.get('specialty_labels') or []) or '—'}."
    w = WEIGHTS[urgency]
    art = 'an' if urgency == 'emergency' else 'a'
    weights_txt = f"Treated as {art} {urgency} need, so the score weights are evidence {w['evidence']}, access {w['access']}, readiness {w['readiness']}, trust {w['trust']} — " + {'emergency': 'access matters most because hours matter.', 'recurring': 'evidence and access both matter for regular treatment.', 'planned': 'evidence matters most; distance is less critical.'}[urgency]
    return {'service': svc, 'location': location['note'], 'weights': weights_txt, 'widening': search_notes, 'urgency': urgency, 'final_search_radius_km': float(final_radius_km)}

# ===== Step 6 — recommend =====
def _ensure_query_log_recommend():
    if not _table_exists('query_log_recommend'):
        spark.sql(f'CREATE OR REPLACE TABLE {SCHEMA}.query_log_recommend (timestamp TIMESTAMP, service_text STRING, location_text STRING, status STRING, service_id STRING, location_label STRING, top3 ARRAY<STRING>)')

def _log_recommend(ts, service_text, location_text, out):
    _ensure_query_log_recommend()
    top3 = [r['unique_id'] for r in out.get('results') or []][:3]
    row = spark.createDataFrame([(ts, str(service_text), str(location_text), out['status'], (out.get('service_resolution') or {}).get('service_id'), (out.get('location_resolution') or {}).get('label'), top3)], 'timestamp timestamp, service_text string, location_text string, status string, service_id string, location_label string, top3 array<string>')
    row.write.mode('append').saveAsTable(f'{SCHEMA}.query_log_recommend')

def _recommend_parts(service_text, location_text, use_llm=True):
    """The full pipeline; returns the public dict plus _scored/_candidates for STEP 8."""
    svc = resolve_service(service_text, use_llm=use_llm)
    loc = resolve_location(location_text)

    def base(status):
        return {'status': status, 'service_resolution': svc, 'location_resolution': loc, 'results': [], 'search_notes': [svc['note'], loc['note']], 'how_we_decided': {'service': svc['note'], 'location': loc['note'], 'weights': None, 'widening': []}}
    if svc['status'] == 'ambiguous':
        return base('needs_service_clarification')
    if loc['status'] == 'ambiguous':
        return base('needs_location_clarification')
    if svc['status'] == 'none':
        return base('unknown_service')
    if loc['status'] == 'none':
        return base('unknown_location')
    cand = get_candidates(svc, loc)
    urgency = urgency_for(svc)
    scored = score_candidates(cand['candidates'], urgency)
    picks = pick_top3(scored)
    results = [explain_result(p, svc, WEIGHTS[urgency]) for p in picks]
    notes = list(cand['search_notes'])
    if not results:
        status = 'no_results'
        n = cand.get('nearest_evidence')
        if n:
            notes.append(f"The nearest facility with any evidence of this service is {n['name']}, {n['distance_km']:.0f} km away (evidence tier: {n['evidence_tier']}).")
    else:
        status = 'ok'
    return {'status': status, 'service_resolution': svc, 'location_resolution': loc, 'results': results, 'search_notes': notes, 'how_we_decided': how_we_decided(svc, loc, urgency, notes, cand['search_radius_km']), '_scored': scored, '_candidates': cand}

def recommend(service_text, location_text, use_llm=True):
    """STEP 6 — the app's entry point. Logs every call."""
    ts = datetime.now()
    parts = _recommend_parts(service_text, location_text, use_llm=use_llm)
    out = {k: parts[k] for k in ['status', 'service_resolution', 'location_resolution', 'results', 'search_notes', 'how_we_decided']}
    _log_recommend(ts, service_text, location_text, out)
    return out
